# src/api.py — FastAPI com Pydantic e health check
from fastapi import FastAPI
from pydantic import BaseModel, Field
import joblib
import pandas as pd

app = FastAPI(title='ML Capstone API', version='1.0.0')
model = joblib.load('artifacts/model.pkl')

class PredictRequest(BaseModel):
    features: dict[str, float | str | None] = Field(..., description='Feature map')

class PredictResponse(BaseModel):
    probability: float
    model_version: str

@app.get('/health')
def health() -> dict[str, str]:
    return {'status': 'ok'}

@app.post('/predict', response_model=PredictResponse)
def predict(req: PredictRequest) -> PredictResponse:
    X = pd.DataFrame([req.features])
    proba = float(model.predict_proba(X)[0, 1])
    return PredictResponse(probability=proba, model_version='1.0.0')
